-- school-registration-turkey  ←  4 صفحة
UPDATE articles SET
    documents = ARRAY['بطاقة الكملك أو إقامة الطفل', 'صور شخصية (2 نسخ)', 'شهادة ميلاد الطفل (أو وثيقة من الكملك)', 'شهادة مدرسية سابقة إن وُجدت (مترجمة)', 'هوية الطفل (كملك/إقامة/هوية) إن وجدت + هويات الأبوين.', 'وثيقة عنوان/سند إقامة (Yerleşim Yeri Belgesi) أو إثبات عنوان من النفوس.', 'شهادة/وثائق المدرسة السابقة + ترجمة عند الحاجة.', 'وثيقة معادلة (Denklik) إذا طُلبت للصف/المرحلة.', 'بطاقة لقاحات/سجل صحي (قد يُطلب حسب المدرسة/المرحلة).']::text[],
    steps = ARRAY['حدد أقرب مدرسة حكومية لمنزلك', 'توجه للمدرسة مع الأوراق المطلوبة', 'قدّم طلب التسجيل لإدارة المدرسة', 'قد يُطلب اختبار تحديد مستوى للأطفال الأكبر سناً', 'استلم جدول الدوام وابدأ الدراسة', 'ثبت عنوانك في النفوس أولاً لأن المدرسة تُحدد حسب المنطقة المسجلة.', 'اسأل المدرسة القريبة أو مديرية التربية عن المدرسة المخصصة لعنوانك (خصوصاً عند الانتقال).', 'إذا طُلبت معادلة (Denklik): جهّز الأوراق وراجع مديرية التربية للحصول عليها.', 'قدّم ملف التسجيل في المدرسة مع جميع النسخ، واطلب قائمة نواقص مكتوبة إن وُجدت.', 'تابع قرار التسجيل/الصف، واحتفظ بأي رقم طلب أو وثيقة استلام.', 'قدّم الوثائق وسجّل الطفل — وتابع عبر منصة e-Okul', 'راجع إدارة المدرسة الحالية واسأل عن إجراء “Nakil” وما إذا كان سيتم عبر النظام مباشرة.']::text[],
    tips = ARRAY['التعليم مجاني تماماً في المدارس الحكومية', 'إذا لم يتقبل طفلك اللغة التركية بسرعة، اسأل عن فصول الدعم (Uyum Sınıfı)', 'بعض المدارس توفر وجبات غداء مجانية', 'ابدأ مبكراً قبل بداية العام الدراسي لأن المواعيد والضغط تكون أعلى في سبتمبر.', 'الاسم وتاريخ الميلاد يجب أن يطابقا الهوية حرفياً لتجنب تأخير إدخال النظام.', 'التسجيل المدرسي يرتبط مباشرةً بعنوانك المثبت في النفوس (Nüfus) لأنه يحدد “مدرسة المنطقة”.', 'قد تحتاج أيضاً إلى معادلة شهادة (Denklik) أو وثائق من المدرسة السابقة.', 'كثير من المشاكل تأتي من عنوان غير مثبت أو وثائق ناقصة، لذلك جهّز ملفاً كاملاً قبل الذهاب.', 'برنامج PICTES يقدّم دعماً تعليمياً للطلاب السوريين — اسأل عنه في المدرسة', 'بعض المدارس الخاصة تقدم منحاً للطلاب المتفوقين', 'مدارس إمام خطيب خيار جيد ومجاني مع تعليم ديني', 'العنوان هو المفتاح الأول للتسجيل؛ حلّه قبل أي خطوة.', 'إذا كان الطفل كبيراً ولم يدرس سابقاً، اسأل عن صف التوجيه/التحديد (Seviye) حسب النظام.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'school-registration-turkey';

-- diploma-denklik-syrians-arabs-2026  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['الشهادة الجامعية الأصلية + ترجمة محلّفة', 'كشف الدرجات الكامل مترجم ومصدّق', 'شهادة الثانوية (للسوريين قد تكون اختيارية)', 'جواز سفر/كملك + صورة منه', 'إيصال دفع 1,250 ل.ت', 'صورة بيومترية حديثة']::text[],
    steps = ARRAY['سجّل في denklik.yok.gov.tr وارفع الوثائق إلكترونياً', 'أرسل الوثائق الأصلية + المترجمة + المصدّقة بالبريد المسجَّل إلى YÖK أنقرة', 'ادفع رسم 1,250 ل.ت 2026', 'انتظر 1-6 أشهر حسب تعقيد الملف', 'احصل على Denklik كاملة أو مشروطة (قد تحتاج امتحان STS)', 'راجع مديرية التربية الوطنية (İl/İlçe Milli Eğitim) في ولايتك أو اتبع النظام المعتمد في ولايتك.', 'توجه لمديرية التربية في ولايتك']::text[],
    tips = ARRAY['السوريون والعراقيون والفلسطينيون يحصلون على تسهيلات خاصة', 'للوثائق المفقودة: اتصل بالجامعة أو القنصلية لإصدار بدائل', 'المهن المنظّمة (طب، صيدلة) غالباً تتطلب امتحان STS', 'إذا رُفض طلبك، فكّر بالطعن — نسبة نجاح القضايا 30-40%', 'الإجراءات تستغرق 1-6 أشهر — لا تتأخر في البدء', 'حتى بدون شهادة أصلية، يمكنك إجراء اختبار بديل', 'المعادلة مجانية في مديرية التربية الحكومية', 'الاختبار يكون عادةً بالتركية — لكن بعض الولايات توفره بالعربية']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'diploma-denklik-syrians-arabs-2026';

-- study-in-turkey-universities-2026  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['شهادة الثانوية + ترجمة مصدّقة', 'كشف علامات + ترجمة', 'جواز سفر ساري', 'صور بيومترية', 'رسالة دافع (للمنح)', 'رسائل توصية (للماجستير)', 'شهادة الثانوية المعدلة (Dengi)']::text[],
    steps = ARRAY['حدد التخصص والجامعات المناسبة', 'قدّم على المنحة التركية (يناير-فبراير)', 'سجّل لامتحان YÖS (أبريل-يونيو)', 'عادل شهادة الثانوية', 'قدّم أوراقك للجامعة', 'بعد القبول قدّم على تأشيرة طالب', 'سجّل بالجامعة واحصل على إقامة الطالب', 'TR-YÖS: امتحان مركزي يجريه ÖSYM مرتين سنوياً.']::text[],
    tips = ARRAY['قدّم على المنحة حتى لو معدلك 70% — رسالة الدافع تفرق كتير', 'سجّل بـ YÖS لأكتر من جامعة', 'سكن KYK أرخص بكتير', 'تعلّم التركية — أغلب البرامج بالتركية']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'study-in-turkey-universities-2026';

-- yks-vs-yos-placement-by-schooling-2026  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['الشهادة الثانوية (تركية للمسار YKS، أو أجنبية مع معادلة MEB للمسار YÖS)', 'معادلة الشهادة الثانوية (Denklik) من وزارة التربية الوطنية MEB — للشهادات غير التركية فقط', 'جواز سفر ساري أو بطاقة إقامة / حماية مؤقتة (الكملك)', 'وثيقة تُثبت مكان إتمام الثانوية (شهادة التخرّج / كشف العلامات)', 'إثبات القيد للمسجَّلين في مدارس السفارات أو المدارس الدولية MOBIS أو مشروع MEB/YÖK (لمن يستند إلى الاستثناء)', 'نتيجة الامتحان المطلوب: YKS (TYT/AYT/YDT) أو TR-YÖS، أو نتيجة امتحان دولي بديل مقبول (SAT / Abitur / IB) حسب الجامعة']::text[],
    steps = ARRAY['حدّد أولاً أين أنهيت ثانويتك: داخل تركيا في مدرسة تركية رسمية، أم خارج تركيا', 'إن أنهيتها داخل تركيا في مدرسة تركية رسمية فمسارك YKS (TYT/AYT وYDT عند الحاجة) عبر مؤسسة القياس ÖSYM', 'إن كنت في مدرسة سفارة أو مدرسة دولية مُدرَجة في نظام MOBIS أو ضمن مشروع MEB/YÖK، فتحقّق رسمياً من أهليتك لمسار YÖS / TR-YÖS رغم دراستك داخل تركيا', 'إن أنهيت ثانويتك خارج تركيا فمسارك YÖS / TR-YÖS؛ استخرج معادلة الشهادة (Denklik) من MEB لأنّها لازمة للشهادات غير التركية', 'راجع نافذة الانتقال بدقّة سنة التسجيل: مَن سُجِّل قبل العام الدراسي 2022-2023 صار YKS فقط من 2026، ومَن سُجِّل من 2022-2023 فصاعداً هو YKS فقط', 'اطّلع على دليل كل جامعة تستهدفها لمعرفة حصصها (kontenjan) وشروطها والامتحانات البديلة التي تقبلها (SAT / Abitur / IB)', 'سجّل للامتحان المطلوب في مواعيده الرسمية عبر ÖSYM، ثم تابِع مرحلة التفضيل والتقديم بعد النتيجة', 'تابع إعلان ÖSYM لمواعيد التسجيل والامتحان لأن الجدول يتغير سنوياً.']::text[],
    tips = ARRAY['المعيار هو مكان إنهاء الثانوية (داخل/خارج تركيا) لا الجنسية؛ لا يوجد شرط جنسية تركية للتقدّم لـ YKS', 'تغيير 2026: الأجنبي الذي درس أو تخرّج من الثانوية داخل تركيا لم يعد يُقبل في حصص YÖS/TR-YÖS وصار مساره YKS', 'استثناء جوهري: طلاب مدارس السفارات، والمدارس الدولية المُدرَجة في MOBIS، وطلاب مشروع MEB/YÖK يبقون مؤهّلين لـ YÖS رغم دراستهم داخل تركيا — تحقّق رسمياً من أهليتك', 'سنة التسجيل هي الفيصل في نافذة الانتقال، والحدّ الفاصل هو العام الدراسي 2022-2023؛ لا تعتمد على كلام عام عن «الدفعات القديمة»', 'معادلة الشهادة (Denklik) من MEB تلزم فقط للشهادات غير التركية؛ خرّيج الثانوية التركية لا يحتاجها', 'الحصص والشروط والمواعيد تختلف بين الجامعات وتتغيّر سنوياً؛ تحقّق رسمياً من دليل ÖSYM/YÖK والجامعة قبل أيّ قرار', 'لا تنتظر صدور النتيجة لتبدأ تجهيز الترجمة/النوتر؛ حضّر الملف مسبقاً.', 'اختر جامعات متعددة ولا تعتمد على خيار واحد فقط.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'yks-vs-yos-placement-by-schooling-2026';

-- tourist-vs-student-residence-2025  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['للسياحية: عقد إيجار/عنوان مثبت + تأمين صحي + كشف حساب/إثبات قدرة مالية + رسالة نية عند الحاجة.', 'للطلابية: وثيقة طالب حديثة + إثبات تسجيل/قبول + عنوان سكن + تأمين صحي مناسب.', 'للنوعين: جواز/وثيقة + صور بيومترية + نموذج/طلب e-ikamet وإيصالات الرسوم حسب ما يظهر في النظام.', 'وثيقة طالب حديثة من الجامعة (Öğrenci Belgesi).']::text[],
    steps = ARRAY['حدد هدفك الحقيقي: دراسة فعلية أم بقاء مؤقت؟ اختيار نوع لا يناسب هدفك يزيد احتمال الرفض.', 'تحقق من متطلبات ولايتك (خصوصاً العنوان/المناطق المغلقة) قبل توقيع عقد سكن أو دفع رسوم.', 'جهّز وثائقك الأساسية واملأ بيانات e-ikamet بدقة كما في الجواز.', 'رتّب الملف (أصل + نسخ) واذهب للموعد/التسليم حسب الإجراء المعتمد في ولايتك.', 'تابع حالة الطلب عبر القنوات الرسمية، وتجاوب سريعاً مع أي طلب “نقص”.', 'قدّم الطلب عبر بوابة e-ikamet واختر نوع الإقامة: Öğrenci İkameti.']::text[],
    tips = ARRAY['لا تعتمد على “معلومة عامة” عن التجديد أو المدة؛ التطبيق يختلف بين الولايات ويتغير مع الوقت.', 'لا تخلط بين “إقامة” و“إذن عمل”: العمل غالباً يحتاج إذن عمل حتى لو كانت الإقامة سارية.', 'إذا كنت طالباً فعلياً: حافظ على وثيقة طالب حديثة وعنوان ثابت لأنهما أكثر سببين للتأخير.', 'لا تستخدم وثيقة طالب قديمة جداً؛ بعض الجهات ترفضها إذا كانت خارج مدة معقولة.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'tourist-vs-student-residence-2025';

-- سدّ حقول المصدر -------------------------------------------------------
UPDATE articles SET source = 'سلسلة التصديق المعمول بها: تصديق الوثيقة التركية لدى الجهة التركية المختصة (الولاية — Valilik — أو الجهة التي تُصدّق حسب نوع الوثيقة)، ثمّ تصديقها في القنصلية العامة للجمهورية العربية السورية. والتفاصيل والرسوم تتغيّر، فأكّدها في القنصلية قبل التوجّه — راجع دليل القنصليات على /consulates.', last_update = CURRENT_DATE
WHERE slug = 'document-attestation-turkey-to-syria-students-2026' AND coalesce(trim(source), '') = '';

UPDATE articles SET source = 'مراكز تعليم اللغة التركية للأجانب (TÖMER) التابعة للجامعات التركية — شروط التسجيل والمستويات والرسوم تحدّدها كل جامعة على حدة، فراجع صفحة المركز في الجامعة التي تقصدها.', last_update = CURRENT_DATE
WHERE slug = 'tomer-registration' AND coalesce(trim(source), '') = '';

-- الصفحات المدموجة تُحذف بعد نقل ما يستحقّ
DELETE FROM articles WHERE slug IN ('enroll-child-turkish-public-school', 'school-transfer', 'school-types-turkey', 'kimlik-school-enrollment', 'highschool-denklik', 'school-equivalency', 'education-universities', 'yos-exam-guide', 'student-residence');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول 5 صفوف، والثاني صفر، والثالث 4 صفوف (المنح كلّها باقية)
SELECT slug, coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0) AS tips, last_update
FROM articles WHERE slug IN ('school-registration-turkey', 'diploma-denklik-syrians-arabs-2026', 'study-in-turkey-universities-2026', 'yks-vs-yos-placement-by-schooling-2026', 'tourist-vs-student-residence-2025') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('enroll-child-turkish-public-school', 'school-transfer', 'school-types-turkey', 'kimlik-school-enrollment', 'highschool-denklik', 'school-equivalency', 'education-universities', 'yos-exam-guide', 'student-residence');

SELECT slug FROM articles WHERE slug IN
  ('scholarship-turkiye-burslari', 'scholarship-university-programs',
   'scholarship-application-tips', 'scholarship-turkey-overview') ORDER BY slug;
